package dev.linqfy.bigCasares.modules.alexscaves.core.block.remap;

import dev.linqfy.bigCasares.modules.alexscaves.core.block.BlockBase;
import dev.linqfy.bigCasares.modules.alexscaves.core.block.CustomBlockState;
import dev.linqfy.bigCasares.modules.alexscaves.core.block.ModBlockRegistry;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * {@code alexscaves/client-remap.txt} (generated by tools/alexscaves/generate_content.py, see
 * {@code block_bases.client_remap}): the vanilla state Java clients receive
 * instead of a module state, dry and/or in water, and the canonical state real vanilla blocks in a borrowed state are
 * sent as. Lines:
 * <pre>
 * block &lt;id&gt; &lt;variant&gt; &lt;base&gt; &lt;index&gt; &lt;dry state|-&gt; &lt;wet state|-&gt;
 * normalize &lt;borrowed state&gt; &lt;canonical state&gt;
 * </pre>
 * Every client state is borrowed once and normalised; canonical states are never borrowed, so one id lookup per
 * block is enough (no chains).
 */
public final class ClientRemapTable {
    private static final Pattern STATE = Pattern.compile("minecraft:[a-z0-9_]+\\[[a-z_]+=[a-z0-9_]+(,[a-z_]+=[a-z0-9_]+)*]");

    private final List<Entry> entries;
    private final Map<String, String> normalize;

    private ClientRemapTable(List<Entry> entries, Map<String, String> normalize) {
        this.entries = List.copyOf(entries);
        this.normalize = Collections.unmodifiableMap(new LinkedHashMap<>(normalize));
    }

    public static ClientRemapTable empty() {
        return new ClientRemapTable(List.of(), Map.of());
    }

    /** Strict: the file is packaged data, a broken line is a build error. */
    public static ClientRemapTable parse(String text) {
        List<Entry> entries = new ArrayList<>();
        Map<String, String> normalize = new LinkedHashMap<>();
        Set<CustomBlockState> servers = new HashSet<>();
        Set<String> clients = new HashSet<>();
        int lineNumber = 0;
        for (String line : text.split("\\R")) {
            lineNumber++;
            String trimmed = line.trim();
            if (trimmed.isEmpty() || trimmed.startsWith("#")) {
                continue;
            }
            String[] tokens = trimmed.split("\\s+");
            try {
                if (tokens[0].equals("block") && tokens.length == 7) {
                    BlockBase base = BlockBase.byId(tokens[3])
                        .orElseThrow(() -> new IllegalArgumentException("base desconocida " + tokens[3]));
                    Entry entry = new Entry(tokens[1], tokens[2], new CustomBlockState(base, Integer.parseInt(tokens[4])),
                        state(tokens[5]), state(tokens[6]));
                    if (!servers.add(entry.server())) {
                        throw new IllegalArgumentException("estado del servidor repetido " + entry.serverState());
                    }
                    for (String client : entry.clientStates()) {
                        if (!clients.add(client)) {
                            throw new IllegalArgumentException(client + " usado dos veces");
                        }
                    }
                    entries.add(entry);
                } else if (tokens[0].equals("normalize") && tokens.length == 3) {
                    String borrowed = state(tokens[1]);
                    String canonical = state(tokens[2]);
                    if (borrowed == null || canonical == null || borrowed.equals(canonical)) {
                        throw new IllegalArgumentException("normalización inválida");
                    }
                    if (normalize.putIfAbsent(borrowed, canonical) != null) {
                        throw new IllegalArgumentException(borrowed + " normalizado dos veces");
                    }
                } else {
                    throw new IllegalArgumentException("formato inválido");
                }
            } catch (IllegalArgumentException invalid) {
                throw new IllegalStateException("client-remap.txt línea " + lineNumber + ": " + invalid.getMessage(), invalid);
            }
        }
        for (String canonical : normalize.values()) {
            if (normalize.containsKey(canonical)) {
                throw new IllegalStateException("client-remap.txt: " + canonical + " es canónico y prestado a la vez");
            }
        }
        if (!clients.equals(normalize.keySet())) {
            throw new IllegalStateException("client-remap.txt: los estados prestados y los normalizados no coinciden");
        }
        return new ClientRemapTable(entries, normalize);
    }

    private static String state(String token) {
        if (token.equals("-")) {
            return null;
        }
        if (!STATE.matcher(token).matches()) {
            throw new IllegalArgumentException("estado inválido " + token);
        }
        return token;
    }

    public List<Entry> entries() {
        return entries;
    }

    /** Borrowed client state -> canonical state, for real vanilla blocks. */
    public Map<String, String> normalize() {
        return normalize;
    }

    public boolean isEmpty() {
        return entries.isEmpty();
    }

    /**
     * The entries usable with a registry: without Paper's tripwire / chorus plant options (see
     * {@link ModBlockRegistry#shapedBasesActive}) those blocks stay on their legacy note block state, which keeps
     * today's look, so their entries are left out, with the normalisations of their client states.
     */
    public ClientRemapTable forRegistry(ModBlockRegistry registry) {
        if (registry.shapedBasesActive()) {
            return this;
        }
        List<Entry> kept = new ArrayList<>();
        Map<String, String> used = new LinkedHashMap<>();
        for (Entry entry : entries) {
            if (entry.server().base() == BlockBase.NOTE_BLOCK) {
                kept.add(entry);
                for (String client : entry.clientStates()) {
                    used.put(client, normalize.get(client));
                }
            }
        }
        return new ClientRemapTable(kept, used);
    }

    /**
     * Entries whose server state no longer draws the named block (blocks.yml and client-remap.txt come from the same
     * generation, so this is a packaging error).
     */
    public List<String> mismatches(ModBlockRegistry registry) {
        List<String> problems = new ArrayList<>();
        for (Entry entry : entries) {
            Optional<CustomBlockState> state = registry.state(entry.blockId(), entry.variant());
            if (state.isEmpty() || !state.get().equals(entry.server())) {
                problems.add(entry.blockId() + " " + entry.variant() + " no es " + entry.serverState());
            }
        }
        return problems;
    }

    /** One module state and what Java clients receive instead, dry and in water ({@code null}: unchanged). */
    public record Entry(String blockId, String variant, CustomBlockState server, String dry, String wet) {
        public Entry {
            if (!server.allocatable()) {
                throw new IllegalArgumentException("estado vanilla reservado: " + server);
            }
            if (dry == null && wet == null) {
                throw new IllegalArgumentException(blockId + " " + variant + " sin estado de cliente");
            }
            if (dry != null && dry.equals(wet)) {
                throw new IllegalArgumentException(blockId + " " + variant + ": mismo estado seco y en agua");
            }
        }

        public String serverState() {
            return server.blockDataString();
        }

        public List<String> clientStates() {
            List<String> states = new ArrayList<>(2);
            if (dry != null) {
                states.add(dry);
            }
            if (wet != null) {
                states.add(wet);
            }
            return states;
        }
    }
}
